      "kb.spv2": "6 軸陀螺儀體感滑鼠＋滑鼠按鍵",
      "kb.spk3": "無線",
      "kb.spv3": "Bluetooth 5.2 ＋ USB-C 有線",
      "kb.spk4": "背光",
      "kb.spv4": "可調式白色 LED",
      "kb.spk5": "電池",
      "kb.spv5": "可充電 Li-Po，USB-C",
      "kb.spk6": "尺寸",
      "kb.spv6": "139 × 78 × 13 mm · 120 g",
      "kb.q1": "我可以搭配什麼使用？",
      "kb.a1": "任何支援 Bluetooth 或 USB HID 鍵盤的裝置——手機、平板、智慧電視、單板電腦，當然還有 TypixDeck。",
      "kb.q2": "電池可使用多久？",
      "kb.a2": "一般使用每次充電可用數週。它透過 USB-C 充電，且可邊充邊用。",
      "kb.cta.t": "為你的配備加上一個鍵盤",
      "kb.cta.p": "你 TypixDeck 的口袋良伴——卡片大小的機身中容納完整配列、體感滑鼠與背光。",
      "doc.diy": "DIY Suite — 開源鍵盤組裝套件 | TypixNode",
      "diy.h1": "焊出你自己的<br/><span class=\"grad\">鍵盤。</span>",
      "diy.lead": "一套開源組裝套件，讓一個下午化為你親手打造的鍵盤。穿孔焊接友善的 PCB、圖解的逐步指南，以及令人滿足的清脆手感——無需經驗。",
      "diy.s1l": "組裝時間",
      "diy.s2l": "按鍵",
      "diy.s3l": "韌體",
      "diy.s4l": "開源",
      "diy.row.t": "充實的一個下午",
      "diy.row.p": "一切都在盒子裡——PCB、定位板、軸體、鍵帽，以及圖解指南。逐步跟著做，最後完成一塊完全屬於你的鍵盤。",
      "diy.feat": "是套件，不是苦差事",
      "diy.f1t": "新手友善",
      "diy.f1p": "穿孔焊接、有標示的零件，以及圖解指南。只要你能拿穩烙鐵，就能組裝它。",
      "diy.f2t": "開源 PCB",
      "diy.f2p": "完整的 PCB 設計與物料清單皆公開——重新混搭配列，讓它成為你的。",
      "diy.f3t": "QMK 韌體",
      "diy.f3p": "重新對應每一個按鍵、新增層與巨集，並完全依你的喜好調校鍵盤。",
      "diy.spk1": "配列",
      "diy.spv1": "48 鍵 ortholinear",
      "diy.spk2": "PCB",
      "diy.spv2": "開源、穿孔式",
      "diy.spk3": "韌體",
      "diy.spv3": "QMK 相容",
      "diy.spk4": "軸體",
      "diy.spv4": "熱插拔相容腳位",
      "diy.spk5": "內容物",
      "diy.spv5": "PCB、定位板、軸體、鍵帽、指南",
      "diy.spk6": "組裝時間",
      "diy.spv6": "約 2 小時",
      "diy.q1": "我需要焊接經驗嗎？",
      "diy.a1": "不需要。本套件使用新手友善的穿孔元件，並隨附圖解的逐步指南。你只需要一支基本的烙鐵。",
      "diy.q2": "我可以自訂配列嗎？",
      "diy.a2": "可以。PCB 設計為開源，且鍵盤運行 QMK，所以你能重新對應按鍵、新增層與巨集，甚至 fork 這個硬體。",
      "diy.cta.t": "親手打造它",
      "diy.cta.p": "開源 PCB、圖解指南與令人滿足的清脆手感——你的第一塊鍵盤，從頭做到尾。",
      "doc.mac": "Pico-Mac Nano — 掌上型 1984 年 Macintosh | TypixNode",
      "mac.h1": "一台 1984 年的 Macintosh，<br/><span class=\"grad\">就在你的手掌中。</span>",
      "mac.lead": "一款用心打造的原版 Macintosh 微縮模型，真的能啟動經典 Mac OS。透過 USB-C 供電，看著 Happy Mac 出現在精緻的小螢幕上，運行真正的復古軟體。",
      "mac.s1l": "螢幕",
      "mac.s2l": "啟動",
      "mac.s3l": "重量",
      "mac.s4l": "供電",
      "mac.row.t": "Happy Mac 再次活了過來",
      "mac.row.p": "這不是螢幕上的一張圖片——它會啟動模擬的經典 Macintosh，連同微笑的 Mac，接著在精緻的小螢幕上運行符合那個年代的軟體。",
      "mac.feat": "小機器，真靈魂",
      "mac.f1t": "啟動真正的 Mac OS",
      "mac.f1p": "在內建螢幕上運行模擬的經典 Macintosh System，包含 Happy Mac。",
      "mac.f2t": "USB-C 供電",
      "mac.f2p": "無需電池、毫不麻煩——插入任何 USB-C 連接埠，System 就在數秒內啟動。",
      "mac.f3t": "忠實的微縮模型",
      "mac.f3p": "仿照 1984 年原版打造，細至米色曲線與磁碟插槽——一款有真靈魂的桌上玩物。",
      "mac.spk1": "螢幕",
      "mac.spv1": "2 吋，經典黑白介面",
      "mac.spk2": "系統",
      "mac.spv2": "模擬的經典 Mac OS（Happy Mac）",
      "mac.spk3": "供電",
      "mac.spv3": "USB-C，無內建電池",
      "mac.spk4": "儲存",
      "mac.spv4": "含系統映像的 microSD",
      "mac.spk5": "機身",
      "mac.spv5": "射出成型，忠於 1984 年原版",
      "mac.spk6": "尺寸",
      "mac.spv6": "60 × 44 × 66 mm · 90 g",
      "mac.q1": "它真的能運行 Mac OS 嗎？",
      "mac.a1": "可以——它會在內建螢幕上啟動模擬的經典 Macintosh System，連同 Happy Mac，並可運行符合那個年代的軟體。",
      "mac.q2": "它如何供電？",
      "mac.a2": "透過 USB-C。沒有內建電池；插入任何 USB-C 電源，它就在數秒內啟動。",
      "mac.cta.t": "把 1984 放上你的桌面",
      "mac.cta.p": "一台真的能啟動的掌上型 Macintosh——電腦人能擁有的最迷人的桌上玩物。",
      "about.doc": "關於我們 — TypixNode",
      "about.kicker": "我們的故事",
      "about.h1": "我們只做幾台機器，但做得非常好。",
      "about.lead": "TypixNode 是一間小型工作室，以小批量設計、銑削並實機測試精巧的開源硬體。我們寧願做四件我們愛的東西，也不做四十件我們不愛的。",
      "about.believe": "我們的信念",
      "about.story": "每個盒子裡都有開源 CAD、電路圖與韌體；小批量、手工檢驗；以及你能更換的零件。這就是全部的理念。",
      "about.v1t": "為打開而生",
      "about.v1p": "每件產品都隨附公開的 CAD、電路圖與韌體。如果你擁有它，你就應該能理解並維修它。",
      "about.v2t": "小批量，高用心",
      "about.v2p": "我們以小批量銑削、組裝與測試。每一台都在出貨前經過手工檢驗。",
      "about.v3t": "為耐用而造",
      "about.v3p": "該用金屬的地方用金屬、標準插槽、可更換零件。配得上長久壽命的硬體，而非送進掩埋場。",
      "support.doc": "支援 — TypixNode",
      "support.kicker": "協助與支援",
      "support.h1": "我們在這裡為你提供協助。",
      "support.lead": "出貨、退貨、保固與設定——重點都在下方。仍有困難？寫信給我們，會有真人回覆。",
      "support.s1t": "預購與出貨",
      "support.s1p": "所有品項皆為預購，以小批量製造。預估從下單起 2 週至 2 個月內寄出，並提供全球免運。你的訂單一出貨，我們就會以電子郵件寄送追蹤資訊。部分路線可能需支付關稅。",
      "support.s2t": "退款與退貨",
      "support.s2p": "在你的預購出貨前隨時可全額退款——只要寫信給我們。送達後，未使用且保持原包裝的品項可享 30 天退貨。",
      "support.s3t": "保固",
      "support.s3p": "每台裝置均享有 2 年有限保固，涵蓋製造瑕疵。維修採用原廠且有文件記錄的零件。",
      "support.s4t": "聯絡我們",
      "support.s4p": "來信 support@typixnode.com——我們通常會在一個工作天內回覆。",
