      "deck.h1.v1": "Ein dünner, <span class=\"grad\">handflächengroßer Linux-Computer.</span>",
      "deck.h1.v2": "CNC-Aluminiumgehäuse.<br/><span class=\"grad\">Ein ganzer Computer.</span>",
