      "deck.lead": "Lernen Sie das TypixDeck kennen — eine dünne, handflächengroße Maschine in einem CNC-gefrästen Aluminiumgehäuse, rund um ein Raspberry Pi Compute Module gebaut. Öffnen Sie es, hacken Sie es, machen Sie es zu Ihrem. Weltweiter Versand.",
