      "why.kicker": "Pourquoi TypixNode",
      "why.title": "Conçu petit. Conçu ouvert.",
      "why.1t": "Fanless &amp; silencieux",
      "why.1p": "Les corps en aluminium CNC servent aussi de dissipateurs — performances complètes à 0 dB, sans ventilateur susceptible de lâcher.",
      "why.2t": "Entièrement open-source",
      "why.2p": "Les schémas, le firmware et les fichiers STEP sont tous publics : vous pouvez réparer, modifier et construire sur tout.",
      "why.3t": "Format de poche",
      "why.3p": "D'un ordinateur de poche à un clavier de la taille d'une carte, chaque appareil est fait pour vous suivre partout.",
      "compat.kicker": "Logiciels et compatibilité", "compat.title": "Faites tourner tout ce que vous aimez sur le TypixDeck",
      "compat.sub": "Il fait tourner Linux mainline sur Raspberry Pi — tout l'univers open source vient donc avec. Un aperçu de ce qui fonctionne directement.",
      "compat.g.os": "Systèmes d'exploitation", "compat.g.emu": "Rétrogaming et émulateurs", "compat.g.engine": "Moteurs de jeu et création",
      "compat.g.sdr": "Radio logicielle (SDR)", "compat.g.desktop": "Bureau et développement", "compat.g.media": "Multimédia et bureautique",
      "compat.disc": "Toutes les marques appartiennent à leurs propriétaires respectifs ; les logos sont affichés uniquement pour indiquer la compatibilité logicielle.",
      "cta.home.t": "Commencez avec le TypixDeck",
      "cta.home.p": "Un ordinateur Linux silencieux, ouvert, en aluminium CNC, qui tient dans la main. Construit sur l'écosystème ouvert Raspberry Pi, partagé par des millions de développeurs dans le monde.",
