      "deck.lead": "Conoce la TypixDeck: una máquina delgada del tamaño de la palma, con cuerpo de aluminio mecanizado por CNC y construida en torno a un Raspberry Pi Compute Module. Ábrela, modifícala, hazla tuya. Envío a todo el mundo.",
