      "deck.ship": "· envío a todo el mundo",
      "deck.pricenote": "· solo el cuerpo — sin batería / compute module · envío a todo el mundo (calculado al pagar)",
      "deck.cm0": "+ CM0 (adaptador CM0→CM4 soldado)",
      "deck.cm4": "+ CM4 4GB completo (incl. batería)",
      "deck.cm5": "+ CM5 4GB completo (incl. batería)",
      "deck.coolnote": "El CM0 / CM4 son sin ventilador &amp; silenciosos (0 dB). La versión con CM5 añade un ventilador PWM de 4-pin opcional + carcasa CNC dedicada — en producción.",
      "kb.pricenote": "· Bluetooth · versión con cable $29 · envío a todo el mundo (calculado al pagar)",
