      "st.social": "Construida sobre la plataforma Raspberry Pi — un ecosistema abierto compartido por <b>millones</b> de desarrolladores en todo el mundo.",
      "f.kicker": "Por qué es diferente",
      "f.title": "Todo lo que una computadora diminuta debería ser",
      "f.sub": "Sin ventilador que falle, sin plástico que se flexione, sin firmware bloqueado: solo máquinas bellamente hechas que controlas por completo.",
      "f.1t": "Chasis de aluminio CNC",
      "f.1p": "Tallado de un solo bloque de aluminio 6061-T6, arenado y anodizado. Rígido, fresco al tacto, hecho para durar décadas.",
      "f.2t": "Realmente silencioso — 0 dB",
      "f.2p": "El chasis de aluminio CNC es el disipador: sin ventilador, sin rejillas, sin polvo. El CM0 y el CM4 funcionan totalmente silenciosos a 0 dB. Para la potencia extra del CM5, se está desarrollando una carcasa CNC dedicada con conector para ventilador PWM de 4-pin.",
      "f.3t": "Raspberry Pi CM4 / CM5 / CM0",
      "f.3p": "Coloca el compute module que quieras. El CM0 también encaja mediante el adaptador castellado CM0→CM4 de 132-pin (se vende por separado).",
      "f.4t": "I/O completo",
      "f.4p": "HDMI, USB-C, doble USB-A, Ethernet, GPIO de 40-pin.",
      "f.5t": "CAD y firmware abiertos",
      "f.5p": "Cada archivo STEP, esquemático e imagen en GitHub.",
      "f.6t": "Tamaño de tarjeta de crédito",
      "f.6p": "Más pequeña que tu teléfono, más pesada de lo que parece. Se desliza en una bolsa y corre un escritorio Linux completo en cualquier lugar.",
      "in.kicker": "Hecha para abrirse",
      "in.title": "Cuatro tornillos y ya estás dentro.",
      "in.1": "<b>Fácil de mantener.</b> Tornillos cautivos, conectores etiquetados y un desmontaje documentado: nada de pegamento.",
      "in.2": "<b>Cambia el cerebro.</b> El compute module va sobre un socket estándar. Pasa al CM5 en minutos.",
      "in.3": "<b>Amplíala.</b> Ranura M.2 para NVMe, un conector de 40-pin para HATs y conectores internos para accesorios.",
      "in.4": "<b>Repara, no reemplaces.</b> Los repuestos y el CAD son públicos, así que una tapa rayada nunca significa una computadora nueva.",
      "in.git": "CAD abierto en GitHub ↗",
      "r.1k": "Escritorio silencioso",
      "r.1t": "Un escritorio Linux completo que no hace ningún ruido",
      "r.1p": "Arranca directo en Raspberry Pi OS o en tu distro favorita. Programa, usa SSH, navega y experimenta, con cero ruido de ventilador en tu escritorio.",
      "r.2k": "Entrada de bolsillo",
      "r.2t": "Se empareja con un teclado del tamaño de una tarjeta",
      "r.2p": "Añade el TypixNode BLE Keyboard para una estación de trabajo de bolsillo completa: diseño completo, air-mouse giroscópico y retroiluminación blanca por Bluetooth o USB-C.",
      "r.3k": "Para los curiosos",
      "r.3t": "Hardware que invita a la curiosidad",
      "r.3p": "Desde un Mac de 1984 del tamaño de la palma hasta un kit de teclado para soldar tú mismo, cada dispositivo TypixNode está diseñado para abrirse, entenderse y modificarse.",
      "lu.kicker": "La gama completa",
      "lu.title": "Cuatro máquinas. Elige tu tamaño.",
      "lu.sub": "Un catálogo pequeño y hecho con cuidado: sin relleno, cada producto es algo que nosotros mismos llevaríamos.",
      "sp.kicker": "TypixDeck",
      "sp.title": "Especificaciones técnicas",
