      "sp.compute.v": "Raspberry Pi Compute Module 4 o 5 (en socket) — o CM0 mediante el adaptador castellado CM0→CM4 de 132-pin",
      "sp.chassis.v": "Aluminio 6061-T6 mecanizado por CNC, arenado y anodizado",
      "sp.cooling.v": "Pasiva a 0 dB en CM0/CM4 (el chasis es el disipador); el CM5 añade un conector para ventilador PWM de 4-pin opcional + carcasa CNC dedicada (en desarrollo)",
      "sp.storage.v": "microSD + ranura M.2 NVMe interna",
      "sp.ports.v": "HDMI, USB-C (PD), 2× USB-A, Gigabit Ethernet, GPIO de 40-pin",
      "sp.wireless.v": "Wi-Fi 5 / Bluetooth 5.0 (según el CM)",
      "sp.dim.v": "95 × 62 × 22 mm · 280 g",
      "sp.os.v": "Archivos STEP completos, esquemáticos y firmware en GitHub",
      "faq.kicker": "Bueno saberlo",
      "faq.title": "Preguntas frecuentes",
      "faq.q1": "¿Incluye un Raspberry Pi Compute Module?",
      "faq.a1": "La TypixDeck se envía como kit de chasis. Añade un CM4 o CM5 al pagar, o coloca uno que ya tengas: usa el socket estándar para compute module.",
      "faq.q2": "¿Cómo se mantiene fría una computadora sin ventilador?",
      "faq.a2": "El chasis de aluminio CNC es el disipador. El compute module está acoplado térmicamente al chasis, así que el calor se reparte por todo el cuerpo y se disipa en silencio, incluso bajo carga sostenida.",
      "faq.q3": "¿De verdad puedo abrirla y repararla yo mismo?",
      "faq.a3": "Sí. Cuatro tornillos cautivos, sin pegamento, conectores etiquetados y una guía de desmontaje pública. Hay repuestos y archivos CAD disponibles para que repares o modifiques lo que quieras.",
      "faq.q4": "¿Cuándo se envía mi reserva?",
      "faq.a4": "Todos los artículos son reservas, fabricados en lotes pequeños. El despacho estimado es de 2 semanas – 2 meses desde el pedido; te enviamos el seguimiento por correo cuando se envíe. Envío a todo el mundo (calculado al pagar) y reembolso total en cualquier momento antes de que se envíe el tuyo. Pueden aplicarse aranceles según tu región.",
      "cta.deck.t": "Arma tu laboratorio Linux de bolsillo",
      "cta.deck.p": "Silenciosa, abierta y hecha para abrirse. Impulsada por la plataforma Raspberry Pi y su ecosistema abierto de millones de desarrolladores en todo el mundo.",
      "cta.deck.b2": "Ver todos los productos",
