      "see.all": "Ver todos los productos",
      "look": "Mira por dentro",
      "doc.kb": "BLE Keyboard — teclado inalámbrico del tamaño de una tarjeta | TypixNode",
      "kb.h1": "Un teclado completo,<br/><span class=\"grad\">del tamaño de una tarjeta.</span>",
      "kb.lead": "De bolsillo pero con todas las funciones: un diseño QWERTY completo con air-mouse giroscópico integrado y una nítida retroiluminación blanca. Se empareja por Bluetooth 5.2 o USB-C con teléfonos, tablets, TVs y tu TypixDeck.",
      "kb.s1l": "Inalámbrico",
      "kb.s2l": "Air mouse",
      "kb.s3l": "Peso",
      "kb.s4l": "Carga",
      "kb.row.t": "Apunta sin un mouse",
      "kb.row.p": "Un giroscopio de 6 ejes convierte todo el teclado en un puntero: inclínalo para mover el cursor y haz clic con los pulgares. Perfecto para una TV o una TypixDeck al otro lado de la habitación.",
      "kb.feat": "Pequeño, pero lo hace todo",
      "kb.f1t": "Air-mouse integrado",
      "kb.f1p": "Un puntero giroscópico que apunta al inclinarlo más teclas de mouse dedicadas: sin necesidad de una superficie plana.",
      "kb.f2t": "Retroiluminado y recargable",
