      "kb.q1": "¿Con qué puedo usarlo?",
      "kb.a1": "Con cualquier cosa que admita un teclado HID por Bluetooth o USB: teléfonos, tablets, smart TVs, computadoras de placa única y, por supuesto, la TypixDeck.",
      "kb.q2": "¿Cuánto dura la batería?",
      "kb.a2": "Varias semanas de uso típico por carga. Se carga por USB-C y se puede usar mientras se carga.",
      "kb.cta.t": "Añade un teclado a tu kit",
      "kb.cta.p": "El compañero de bolsillo de tu TypixDeck: diseño completo, air-mouse y retroiluminación en un cuerpo del tamaño de una tarjeta.",
      "doc.diy": "DIY Suite — kit de armado de teclado open-source | TypixNode",
      "diy.h1": "Suelda tu propio<br/><span class=\"grad\">teclado.</span>",
      "diy.lead": "Un kit de armado open-source que convierte una tarde en un teclado que hiciste tú mismo. Una PCB amigable para soldadura through-hole, una guía ilustrada paso a paso y un satisfactorio tacto clicky: no se requiere experiencia.",
      "diy.s1l": "Tiempo de armado",
      "diy.s2l": "Teclas",
      "diy.s3l": "Firmware",
      "diy.s4l": "Open source",
      "diy.row.t": "Una tarde bien aprovechada",
      "diy.row.p": "Todo viene en la caja: PCB, placa, switches, keycaps y una guía ilustrada. Síguela paso a paso y termina con un teclado que es totalmente tuyo.",
      "diy.feat": "Un kit, no una tarea pesada",
      "diy.f1t": "Apto para principiantes",
      "diy.f1p": "Soldadura through-hole, piezas etiquetadas y una guía ilustrada. Si puedes sostener un cautín, puedes armarlo.",
      "diy.f2t": "PCB open-source",
      "diy.f2p": "El diseño completo de la PCB y la lista de materiales son públicos: remezcla el diseño y hazlo tuyo.",
      "diy.f3t": "Firmware QMK",
      "diy.f3p": "Reasigna cada tecla, añade capas y macros, y ajusta el teclado exactamente como te guste.",
      "diy.spk1": "Diseño",
      "diy.spv1": "Ortholinear de 48 teclas",
      "diy.spk2": "PCB",
      "diy.spv2": "Open-source, through-hole",
      "diy.spk3": "Firmware",
      "diy.spv3": "Compatible con QMK",
      "diy.spk4": "Switches",
      "diy.spv4": "Footprints compatibles con hot-swap",
      "diy.spk5": "Incluye",
      "diy.spv5": "PCB, placa, switches, keycaps, guía",
      "diy.spk6": "Tiempo de armado",
      "diy.spv6": "Unas 2 horas",
      "diy.q1": "¿Necesito experiencia soldando?",
      "diy.a1": "No. El kit usa componentes through-hole aptos para principiantes y viene con una guía ilustrada paso a paso. Solo necesitas un cautín básico.",
      "diy.q2": "¿Puedo personalizar el diseño?",
      "diy.a2": "Sí. El diseño de la PCB es open-source y el teclado corre QMK, así que puedes reasignar teclas, añadir capas y macros, e incluso bifurcar el hardware.",
      "diy.cta.t": "Ármalo tú mismo",
      "diy.cta.p": "Una PCB abierta, una guía ilustrada y un click satisfactorio: el armado de tu primer teclado, de principio a fin.",
      "doc.mac": "Pico-Mac Nano — un Macintosh de 1984 del tamaño de la palma | TypixNode",
      "mac.h1": "Un Macintosh de 1984,<br/><span class=\"grad\">en tu palma.</span>",
      "mac.lead": "Una miniatura entrañable del Macintosh original que de verdad arranca el clásico Mac OS. Aliméntalo por USB-C, mira aparecer el Happy Mac en una nítida pantallita y corre software vintage real.",
      "mac.s1l": "Pantalla",
      "mac.s2l": "Arranca",
      "mac.s3l": "Peso",
      "mac.s4l": "Alimentación",
      "mac.row.t": "El Happy Mac vuelve a la vida",
      "mac.row.p": "No es una imagen en una pantalla: arranca un Macintosh clásico emulado, con su Mac sonriente y todo, y luego corre software de la época en una nítida pantallita.",
      "mac.feat": "Máquina diminuta, alma de verdad",
      "mac.f1t": "Arranca Mac OS real",
      "mac.f1p": "Corre un System clásico de Macintosh emulado, Happy Mac incluido, en la pantalla integrada.",
      "mac.f2t": "Alimentado por USB-C",
      "mac.f2p": "Sin baterías, sin complicaciones: conéctalo a cualquier puerto USB-C y el System arranca en segundos.",
      "mac.f3t": "Una miniatura fiel",
      "mac.f3p": "Modelado según el original de 1984 hasta en las curvas beige y la ranura de disquete: un juguete de escritorio con alma de verdad.",
      "mac.spk1": "Pantalla",
      "mac.spv1": "2 pulgadas, clásica UI en blanco y negro",
      "mac.spk2": "Sistema",
      "mac.spv2": "Mac OS clásico emulado (Happy Mac)",
      "mac.spk3": "Alimentación",
      "mac.spv3": "USB-C, sin batería interna",
      "mac.spk4": "Almacenamiento",
      "mac.spv4": "microSD con imagen del sistema",
      "mac.spk5": "Cuerpo",
      "mac.spv5": "Inyectado en molde, fiel a 1984",
      "mac.spk6": "Dimensiones",
      "mac.spv6": "60 × 44 × 66 mm · 90 g",
      "mac.q1": "¿De verdad corre Mac OS?",
      "mac.a1": "Sí: arranca un System clásico de Macintosh emulado, con el Happy Mac incluido, en su pantalla integrada, y puede correr software de la época.",
      "mac.q2": "¿Cómo se alimenta?",
      "mac.a2": "Por USB-C. No tiene batería interna; conéctalo a cualquier fuente USB-C y arranca en unos segundos.",
      "mac.cta.t": "Pon 1984 en tu escritorio",
      "mac.cta.p": "Un Macintosh del tamaño de la palma que de verdad arranca: el juguete de escritorio más encantador que puede tener una persona de las computadoras.",
      "about.doc": "Nosotros — TypixNode",
      "about.kicker": "Nuestra historia",
      "about.h1": "Hacemos unas pocas máquinas, muy bien.",
      "about.lead": "TypixNode es un estudio diminuto que diseña, mecaniza y prueba en banco hardware abierto y compacto en lotes pequeños. Preferimos hacer cuatro cosas que amamos que cuarenta que no.",
      "about.believe": "En qué creemos",
      "about.story": "CAD, esquemáticos y firmware abiertos en cada caja; lotes pequeños revisados a mano; y piezas que puedes reemplazar. Esa es toda la idea.",
      "about.v1t": "Hecho para abrirse",
      "about.v1p": "Cada producto se envía con CAD, esquemáticos y firmware públicos. Si es tuyo, deberías poder entenderlo y repararlo.",
      "about.v2t": "Lotes pequeños, mucho cuidado",
      "about.v2p": "Mecanizamos, ensamblamos y probamos en tiradas pequeñas. Cada unidad se revisa a mano antes de enviarse.",
      "about.v3t": "Hecho para durar",
      "about.v3p": "Metal donde importa, sockets estándar, piezas reemplazables. Hardware que se gana una larga vida, no un basurero.",
      "support.doc": "Soporte — TypixNode",
      "support.kicker": "Ayuda y soporte",
      "support.h1": "Estamos aquí para ayudar.",
      "support.lead": "Envíos, devoluciones, garantía y configuración: lo esencial está abajo. ¿Sigues atascado? Escríbenos y te responde una persona.",
      "support.s1t": "Reserva y envío",
      "support.s1p": "Todos los artículos son reservas, hechos en lotes pequeños. El despacho estimado es de 2 semanas – 2 meses desde el pedido, con envío a todo el mundo (calculado al pagar). Te enviamos el seguimiento por correo en cuanto se envía el tuyo. Pueden aplicarse aranceles en algunas rutas.",
      "support.s2t": "Reembolsos y devoluciones",
      "support.s2p": "Reembolso total en cualquier momento antes de que se envíe tu reserva: solo escríbenos. Tras la entrega, devoluciones en 30 días de artículos sin usar en su empaque original.",
      "support.s3t": "Garantía",
      "support.s3p": "Cada dispositivo lleva una garantía limitada de 2 años contra defectos de fabricación. Las reparaciones usan piezas genuinas y documentadas.",
      "support.s4t": "Contacto",
      "support.s4p": "Escribe a support@typixnode.com: normalmente respondemos en un día hábil.",
