      "deck.lead": "Conheça o TypixDeck — uma máquina fina do tamanho da palma, com corpo de alumínio usinado em CNC e construída em torno de um Raspberry Pi Compute Module. Abra, hackeie, torne-a sua. Enviado para o mundo todo.",
