      "st.social": "Construído sobre a plataforma Raspberry Pi — um ecossistema aberto compartilhado por <b>milhões</b> de desenvolvedores no mundo todo.",
      "f.kicker": "Por que é diferente",
      "f.title": "Tudo o que um computador minúsculo deveria ser",
      "f.sub": "Sem ventoinha que falha, sem plástico que verga, sem firmware trancado — só máquinas lindamente feitas que você controla por completo.",
      "f.1t": "Chassi de alumínio CNC",
      "f.1p": "Esculpido de um único bloco de alumínio 6061-T6, jateado e anodizado. Rígido, frio ao toque, feito para durar décadas.",
      "f.2t": "Totalmente silencioso — 0 dB",
      "f.2p": "O chassi de alumínio CNC é o dissipador — sem ventoinha, sem entradas de ar, sem poeira. CM0 e CM4 funcionam totalmente silenciosos a 0 dB. Para a potência extra do CM5, um case CNC dedicado com header para ventoinha PWM de 4-pin está em desenvolvimento.",
      "f.3t": "Raspberry Pi CM4 / CM5 / CM0",
      "f.3p": "Encaixe o compute module que quiser. O CM0 também cabe via o adaptador CM0→CM4 castelado de 132-pin (vendido separadamente).",
      "f.4t": "I/O completo",
      "f.4p": "HDMI, USB-C, dois USB-A, Ethernet, GPIO de 40-pin.",
      "f.5t": "CAD & firmware abertos",
      "f.5p": "Cada arquivo STEP, esquemático e imagem no GitHub.",
      "f.6t": "Tamanho de cartão de crédito",
      "f.6p": "Menor que seu celular, mais pesado do que parece. Cabe na bolsa e roda um desktop Linux completo em qualquer lugar.",
      "in.kicker": "Feito para ser aberto",
      "in.title": "Quatro parafusos e você está por dentro.",
      "in.1": "<b>Amigável com ferramentas.</b> Parafusos cativos, conectores rotulados e uma desmontagem documentada — sem cola em lugar nenhum.",
      "in.2": "<b>Troque o cérebro.</b> O compute module fica em um socket padrão. Suba para o CM5 em minutos.",
      "in.3": "<b>Expanda.</b> Slot M.2 para NVMe, um header de 40-pin para HATs, headers internos para acessórios.",
