      "sp.compute.v": "Raspberry Pi Compute Module 4 ou 5 (socketed) — ou CM0 via o adaptador CM0→CM4 castelado de 132-pin",
      "sp.chassis.v": "Alumínio 6061-T6 fresado em CNC, jateado & anodizado",
      "sp.cooling.v": "Passivo 0 dB no CM0/CM4 (o chassi é o dissipador); o CM5 adiciona um header para ventoinha PWM de 4-pin opcional + case CNC dedicado (em desenvolvimento)",
      "sp.storage.v": "microSD + slot M.2 NVMe interno",
      "sp.ports.v": "HDMI, USB-C (PD), 2× USB-A, Gigabit Ethernet, GPIO de 40-pin",
