      "faq.kicker": "Bom saber",
      "faq.title": "Perguntas frequentes",
      "faq.q1": "Ele vem com um Raspberry Pi Compute Module?",
      "faq.a1": "O TypixDeck é enviado como um kit de chassi. Adicione um CM4 ou CM5 no checkout, ou encaixe um que você já tem — ele usa o socket padrão de compute module.",
      "faq.q2": "Como um computador sem ventoinha se mantém frio?",
      "faq.a2": "O chassi de alumínio CNC é o dissipador. O compute module é termicamente acoplado ao chassi, então o calor se espalha por todo o corpo e dissipa silenciosamente, mesmo sob carga sustentada.",
      "faq.q3": "Posso mesmo abrir e reparar eu mesmo?",
      "faq.a3": "Sim. Quatro parafusos cativos, sem cola, conectores rotulados e um guia público de desmontagem. Peças de reposição e arquivos CAD estão disponíveis para você reparar ou modificar qualquer coisa.",
      "faq.q4": "Quando minha pré-venda é enviada?",
      "faq.a4": "Todos os itens são pré-vendas, produzidos em pequenos lotes. O despacho estimado é de 2 semanas – 2 meses a partir do pedido; enviamos o rastreio por e-mail quando despacha. Envio para o mundo todo (frete calculado no checkout) e reembolso total a qualquer momento antes do envio do seu. Taxas podem ser aplicadas dependendo da sua região.",
      "cta.deck.t": "Monte seu laboratório Linux de bolso",
      "cta.deck.p": "Silencioso, aberto e feito para ser aberto. Movido pela plataforma Raspberry Pi e seu ecossistema aberto de milhões de desenvolvedores no mundo todo.",
      "cta.deck.b2": "Ver todos os produtos",
