      "doc.kb": "BLE Keyboard — teclado sem fio do tamanho de um cartão | TypixNode",
      "kb.h1": "Um teclado completo,<br/><span class=\"grad\">do tamanho de um cartão.</span>",
      "kb.lead": "Do tamanho de um bolso, mas com recursos completos — um layout QWERTY completo com air-mouse giroscópico embutido e um backlight branco nítido. Conecta via Bluetooth 5.2 ou USB-C com celulares, tablets, TVs e seu TypixDeck.",
