      "kb.q1": "Com o que posso usá-lo?",
      "kb.a1": "Qualquer coisa que suporte um teclado HID Bluetooth ou USB — celulares, tablets, smart TVs, computadores single-board e, claro, o TypixDeck.",
      "kb.q2": "Quanto dura a bateria?",
