      "kb.cta.p": "O companheiro de bolso do seu TypixDeck — layout completo, air-mouse e backlight em um corpo do tamanho de um cartão.",
      "doc.diy": "DIY Suite — kit de montagem de teclado open-source | TypixNode",
      "diy.h1": "Solde seu próprio<br/><span class=\"grad\">teclado.</span>",
      "diy.lead": "Um kit de montagem open-source que transforma uma tarde em um teclado feito por você mesmo. Uma PCB amigável a furo passante, um guia ilustrado passo a passo e um clique satisfatório — sem experiência necessária.",
      "diy.s1l": "Tempo de montagem",
      "diy.s2l": "Teclas",
      "diy.s3l": "Firmware",
      "diy.s4l": "Open source",
      "diy.row.t": "Uma tarde bem aproveitada",
      "diy.row.p": "Tudo está na caixa — PCB, plate, switches, keycaps e um guia ilustrado. Siga passo a passo e termine com um teclado inteiramente seu.",
      "diy.feat": "Um kit, não uma tarefa chata",
      "diy.f1t": "Amigável para iniciantes",
      "diy.f1p": "Solda de furo passante, peças rotuladas e um guia ilustrado. Se você consegue segurar um ferro, consegue montá-lo.",
      "diy.f2t": "PCB open-source",
      "diy.f2p": "O design completo da PCB e a lista de materiais são públicos — remixe o layout e torne-o seu.",
      "diy.f3t": "Firmware QMK",
      "diy.f3p": "Remapeie cada tecla, adicione layers e macros e ajuste o teclado exatamente como você gosta.",
      "diy.spk1": "Layout",
      "diy.spv1": "Ortholinear de 48 teclas",
      "diy.spk2": "PCB",
      "diy.spv2": "Open-source, furo passante",
      "diy.spk3": "Firmware",
      "diy.spv3": "Compatível com QMK",
      "diy.spk4": "Switches",
      "diy.spv4": "Footprints compatíveis com hot-swap",
      "diy.spk5": "Inclui",
      "diy.spv5": "PCB, plate, switches, keycaps, guia",
      "diy.spk6": "Tempo de montagem",
      "diy.spv6": "Cerca de 2 horas",
      "diy.q1": "Preciso de experiência com solda?",
      "diy.a1": "Não. O kit usa componentes de furo passante amigáveis para iniciantes e vem com um guia ilustrado passo a passo. Um ferro de solda básico é tudo o que você precisa.",
      "diy.q2": "Posso personalizar o layout?",
      "diy.a2": "Sim. O design da PCB é open-source e o teclado roda QMK, então você pode remapear teclas, adicionar layers e macros e até fazer um fork do hardware.",
      "diy.cta.t": "Monte você mesmo",
      "diy.cta.p": "Uma PCB aberta, um guia ilustrado e um clique satisfatório — sua primeira montagem de teclado, do início ao fim.",
      "doc.mac": "Pico-Mac Nano — um Macintosh de 1984 do tamanho da palma | TypixNode",
      "mac.h1": "Um Macintosh de 1984,<br/><span class=\"grad\">na sua palma.</span>",
      "mac.lead": "Uma miniatura caprichada do Macintosh original que realmente inicia o clássico Mac OS. Alimente-o via USB-C, veja o Happy Mac surgir em um display pequeno e nítido e rode software vintage de verdade.",
