      "mac.s2l": "Inicia",
      "mac.s3l": "Peso",
      "mac.s4l": "Alimentação",
      "mac.row.t": "O Happy Mac vive de novo",
      "mac.row.p": "Não é uma imagem em uma tela — ele inicia um Macintosh clássico emulado, com Mac sorridente e tudo, e então roda software da época em um display pequeno e nítido.",
      "mac.feat": "Máquina minúscula, alma de verdade",
      "mac.f1t": "Inicia o Mac OS de verdade",
      "mac.f1p": "Roda um System clássico do Macintosh emulado, Happy Mac incluído, no display embutido.",
      "mac.f2t": "Alimentado por USB-C",
