      "mac.spv5": "Injetado, fiel a 1984",
      "mac.spk6": "Dimensões",
      "mac.spv6": "60 × 44 × 66 mm · 90 g",
      "mac.q1": "Ele realmente roda Mac OS?",
      "mac.a1": "Sim — ele inicia um System clássico do Macintosh emulado, completo com o Happy Mac, em seu display embutido, e pode rodar software da época.",
      "mac.q2": "Como ele é alimentado?",
      "mac.a2": "Via USB-C. Não há bateria interna; conecte-o em qualquer fonte USB-C e ele inicia em poucos segundos.",
      "mac.cta.t": "Coloque 1984 na sua mesa",
      "mac.cta.p": "Um Macintosh do tamanho da palma que realmente inicia — o brinquedo de mesa mais charmoso que uma pessoa de tecnologia pode ter.",
      "about.doc": "Sobre — TypixNode",
      "about.kicker": "Nossa história",
      "about.h1": "Fazemos poucas máquinas, muito bem.",
      "about.lead": "A TypixNode é um pequeno estúdio que projeta, fresa e testa em bancada open hardware compacto em pequenos lotes. Preferimos fazer quatro coisas que amamos a quarenta que não amamos.",
      "about.believe": "No que acreditamos",
      "about.story": "CAD, esquemáticos e firmware abertos em cada caixa; lotes pequenos, verificados à mão; e peças que você pode substituir. Essa é a ideia toda.",
      "about.v1t": "Feito para ser aberto",
      "about.v1p": "Cada produto vem com CAD, esquemáticos e firmware públicos. Se é seu, você deve poder compreendê-lo e repará-lo.",
      "about.v2t": "Pequenos lotes, muito cuidado",
      "about.v2p": "Fresamos, montamos e testamos em pequenas tiragens. Cada unidade é verificada à mão antes de ser enviada.",
      "about.v3t": "Feito para durar",
      "about.v3p": "Metal onde importa, sockets padrão, peças substituíveis. Hardware que merece uma vida longa, não um aterro.",
