      "support.s1p": "Todos os itens são pré-vendas, feitos em pequenos lotes. O despacho estimado é de 2 semanas – 2 meses a partir do pedido, com envio para o mundo todo (frete calculado no checkout). Enviamos o rastreio por e-mail no momento em que o seu despacha. Taxas podem ser aplicadas em algumas rotas.",
      "support.s2t": "Reembolsos & devoluções",
      "support.s2p": "Reembolso total a qualquer momento antes do envio da sua pré-venda — basta nos mandar um e-mail. Após a entrega, devoluções em 30 dias para itens não usados na embalagem original.",
      "support.s3t": "Garantia",
      "support.s3p": "Cada dispositivo tem uma garantia limitada de 2 anos contra defeitos de fabricação. Os reparos usam peças genuínas e documentadas.",
