      "deck.h1.v3": "CNC 가공 알루미늄 합금 바디로<br/><span class=\"grad\">하나로 밀폐 성형.</span>",
      "deck.h1.v4": "열고, 만지고,<br/><span class=\"grad\">당신만의 것으로.</span>",
      "deck.h1.v5": "열고 고치고 소유하는<br/><span class=\"grad\">손바닥 크기 컴퓨터.</span>",
      "deck.h1.v6": "만지작거리는 사람을 위한<br/><span class=\"grad\">오픈소스 컴퓨터.</span>",
      "deck.lead": "TypixDeck를 만나보세요 — CNC 가공 알루미늄 합금 바디에 Raspberry Pi Compute Module을 중심으로 설계한 얇고 손바닥 크기의 머신. 열고, 해킹하고, 당신만의 것으로 만드세요. 전 세계 배송.",
