      "f.1t": "CNC 알루미늄 섀시",
      "f.1p": "6061-T6 알루미늄 단일 블록을 깎아 비드 블라스팅 후 아노다이징했습니다. 견고하고, 만지면 시원하며, 수십 년을 견디도록 만들어졌습니다.",
      "f.2t": "진정한 무소음 — 0 dB",
      "f.2p": "CNC 알루미늄 섀시 자체가 방열판입니다 — 팬도, 통풍구도, 먼지도 없습니다. CM0와 CM4는 0 dB로 완전히 무소음으로 동작합니다. CM5의 추가 성능을 위해 4-pin PWM 팬 헤더를 갖춘 전용 CNC 케이스를 개발 중입니다.",
      "f.3t": "Raspberry Pi CM4 / CM5 / CM0",
      "f.3p": "원하는 compute module을 꽂으세요. CM0도 castellated 132-pin CM0→CM4 어댑터(별매)를 통해 장착됩니다.",
      "f.4t": "완전한 I/O",
      "f.4p": "HDMI, USB-C, 듀얼 USB-A, Ethernet, 40-pin GPIO.",
