      "f.5p": "모든 STEP 파일, 회로도, 이미지를 GitHub에 공개합니다.",
      "f.6t": "신용카드 크기",
      "f.6p": "스마트폰보다 작지만, 보기보다 묵직합니다. 가방에 쏙 들어가 어디서나 완전한 Linux 데스크톱을 구동합니다.",
      "in.kicker": "열 수 있도록 만들었습니다",
      "in.title": "나사 네 개면 내부가 보입니다.",
      "in.1": "<b>공구 친화적.</b> 분실 방지 나사, 라벨이 붙은 커넥터, 문서화된 분해 가이드 — 어디에도 접착제가 없습니다.",
      "in.2": "<b>두뇌를 교체하세요.</b> compute module은 표준 소켓에 장착됩니다. 몇 분이면 CM5로 업그레이드할 수 있습니다.",
      "in.3": "<b>확장하세요.</b> NVMe용 M.2 슬롯, HAT용 40-pin 헤더, 애드온용 내부 헤더를 갖췄습니다.",
      "in.4": "<b>교체 대신 수리.</b> 예비 부품과 CAD가 공개되어 있어, 뚜껑에 스크래치가 나도 새 컴퓨터를 살 필요가 없습니다.",
      "in.git": "GitHub에서 오픈 CAD 보기 ↗",
