      "faq.title": "자주 묻는 질문",
      "faq.q1": "Raspberry Pi Compute Module이 포함되어 있나요?",
      "faq.a1": "TypixDeck는 섀시 키트로 배송됩니다. 결제 시 CM4 또는 CM5를 추가하거나, 이미 보유한 모듈을 꽂으세요 — 표준 compute module 소켓을 사용합니다.",
      "faq.q2": "팬리스 컴퓨터가 어떻게 냉각을 유지하나요?",
      "faq.a2": "CNC 알루미늄 섀시가 방열판입니다. compute module이 섀시에 열적으로 접합되어 있어, 열이 본체 전체로 퍼지며 지속적인 부하에서도 무소음으로 방출됩니다.",
      "faq.q3": "정말 직접 열어서 수리할 수 있나요?",
      "faq.a3": "네. 분실 방지 나사 네 개, 접착제 없음, 라벨이 붙은 커넥터, 그리고 공개된 분해 가이드를 제공합니다. 예비 부품과 CAD 파일이 제공되어 무엇이든 수리하거나 개조할 수 있습니다.",
      "faq.q4": "제 사전 예약 제품은 언제 배송되나요?",
      "faq.a4": "모든 제품은 소량 배치로 제작되는 사전 예약 상품입니다. 예상 발송 시기는 주문 후 2주 ~ 2개월이며, 배송 시 추적 정보를 이메일로 보내드립니다. 전 세계 배송 (배송비는 결제 시 계산)이며, 배송 전 언제든 전액 환불이 가능합니다. 지역에 따라 관세가 부과될 수 있습니다.",
      "cta.deck.t": "주머니 속 Linux 실험실을 만들어 보세요",
