      "diy.lead": "오후 한나절을 직접 만든 키보드로 바꿔주는 오픈소스 조립 키트. 스루홀 친화적인 PCB, 그림으로 설명된 단계별 가이드, 그리고 만족스러운 클릭감 — 경험은 필요 없습니다.",
      "diy.s1l": "조립 시간",
      "diy.s2l": "키",
      "diy.s3l": "펌웨어",
      "diy.s4l": "오픈소스",
      "diy.row.t": "잘 보낸 오후 한나절",
      "diy.row.p": "모든 것이 상자 안에 있습니다 — PCB, 플레이트, 스위치, 키캡, 그리고 그림 가이드. 단계별로 따라가면 온전히 당신만의 보드로 완성됩니다.",
      "diy.feat": "번거로운 일이 아닌, 키트",
      "diy.f1t": "초보자 친화적",
      "diy.f1p": "스루홀 납땜, 라벨이 붙은 부품, 그림 가이드. 인두기를 잡을 수 있다면, 만들 수 있습니다.",
      "diy.f2t": "오픈소스 PCB",
      "diy.f2p": "전체 PCB 설계와 BOM(자재 명세서)이 공개되어 있습니다 — 레이아웃을 리믹스해 당신만의 것으로 만드세요.",
      "diy.f3t": "QMK 펌웨어",
      "diy.f3p": "모든 키를 리매핑하고, 레이어와 매크로를 추가하며, 원하는 대로 정확히 보드를 튜닝하세요.",
      "diy.spk1": "레이아웃",
      "diy.spv1": "48키 ortholinear",
      "diy.spk2": "PCB",
      "diy.spv2": "오픈소스, 스루홀",
      "diy.spk3": "펌웨어",
      "diy.spv3": "QMK 호환",
      "diy.spk4": "스위치",
      "diy.spv4": "핫스왑 호환 풋프린트",
      "diy.spk5": "구성품",
      "diy.spv5": "PCB, 플레이트, 스위치, 키캡, 가이드",
      "diy.spk6": "조립 시간",
      "diy.spv6": "약 2시간",
      "diy.q1": "납땜 경험이 필요한가요?",
      "diy.a1": "아니요. 이 키트는 초보자 친화적인 스루홀 부품을 사용하며, 그림으로 설명된 단계별 가이드가 함께 제공됩니다. 기본 인두기만 있으면 충분합니다.",
      "diy.q2": "레이아웃을 커스터마이징할 수 있나요?",
      "diy.a2": "네. PCB 설계가 오픈소스이고 보드가 QMK로 동작하므로, 키를 리매핑하고, 레이어와 매크로를 추가하며, 하드웨어를 포크할 수도 있습니다.",
      "diy.cta.t": "직접 만들어 보세요",
      "diy.cta.p": "오픈 PCB, 그림 가이드, 그리고 만족스러운 클릭감 — 처음부터 끝까지, 당신의 첫 키보드 조립.",
      "doc.mac": "Pico-Mac Nano — 손바닥 크기의 1984년 Macintosh | TypixNode",
      "mac.h1": "손바닥 안의<br/><span class=\"grad\">1984년 Macintosh.</span>",
      "mac.lead": "실제로 classic Mac OS를 부팅하는, 오리지널 Macintosh의 사랑스러운 미니어처. USB-C로 전원을 공급하고, 선명한 작은 디스플레이에 Happy Mac이 나타나는 것을 지켜보며, 진짜 빈티지 소프트웨어를 실행하세요.",
      "mac.s1l": "디스플레이",
      "mac.s2l": "부팅",
      "mac.s3l": "무게",
      "mac.s4l": "전원",
      "mac.row.t": "Happy Mac이 다시 살아납니다",
      "mac.row.p": "화면 속 그림이 아닙니다 — 미소 짓는 Mac까지, 에뮬레이트된 classic Macintosh를 부팅한 뒤 선명한 작은 디스플레이에서 그 시절의 소프트웨어를 실행합니다.",
      "mac.feat": "작은 머신, 진짜 영혼",
      "mac.f1t": "진짜 Mac OS 부팅",
      "mac.f1p": "Happy Mac을 포함한 에뮬레이트된 classic Macintosh System을 내장 디스플레이에서 실행합니다.",
      "mac.f2t": "USB-C 전원",
      "mac.f2p": "배터리도, 번거로움도 없습니다 — 아무 USB-C 포트에 꽂으면 System이 몇 초 만에 시작됩니다.",
      "mac.f3t": "충실한 미니어처",
      "mac.f3p": "베이지색 곡선과 플로피 슬롯까지 1984년 오리지널을 그대로 본떴습니다 — 진짜 영혼을 담은 데스크 토이.",
      "mac.spk1": "디스플레이",
      "mac.spv1": "2인치, 클래식 흑백 UI",
      "mac.spk2": "시스템",
      "mac.spv2": "에뮬레이트된 classic Mac OS (Happy Mac)",
      "mac.spk3": "전원",
      "mac.spv3": "USB-C, 내장 배터리 없음",
      "mac.spk4": "스토리지",
      "mac.spv4": "시스템 이미지가 담긴 microSD",
      "mac.spk5": "본체",
      "mac.spv5": "사출 성형, 1984년 충실 재현",
      "mac.spk6": "크기",
      "mac.spv6": "60 × 44 × 66 mm · 90 g",
      "mac.q1": "정말 Mac OS가 실행되나요?",
      "mac.a1": "네 — Happy Mac과 함께 에뮬레이트된 classic Macintosh System을 내장 디스플레이에서 부팅하며, 그 시절의 소프트웨어를 실행할 수 있습니다.",
      "mac.q2": "전원은 어떻게 공급되나요?",
      "mac.a2": "USB-C를 통해서입니다. 내장 배터리는 없으며, 아무 USB-C 전원에 꽂으면 몇 초 만에 부팅됩니다.",
      "mac.cta.t": "책상 위에 1984년을 올려놓으세요",
      "mac.cta.p": "정말로 부팅되는 손바닥 크기의 Macintosh — 컴퓨터를 좋아하는 사람이 가질 수 있는 가장 매력적인 데스크 토이.",
      "about.doc": "소개 — TypixNode",
      "about.kicker": "우리의 이야기",
      "about.h1": "우리는 몇 가지 머신을, 아주 잘 만듭니다.",
      "about.lead": "TypixNode는 컴팩트 오픈 하드웨어를 소량 배치로 설계하고, 가공하고, 벤치 테스트하는 작은 스튜디오입니다. 사랑하지 않는 마흔 가지보다, 사랑하는 네 가지를 만드는 쪽을 택합니다.",
      "about.believe": "우리가 믿는 것",
      "about.story": "모든 상자에 담긴 오픈 CAD, 회로도, 펌웨어; 작고 손수 검수한 배치; 그리고 교체 가능한 부품. 그것이 우리의 전부입니다.",
      "about.v1t": "열 수 있도록 만듭니다",
      "about.v1p": "모든 제품은 공개된 CAD, 회로도, 펌웨어와 함께 배송됩니다. 소유한 제품이라면, 이해하고 수리할 수 있어야 합니다.",
      "about.v2t": "소량 배치, 높은 정성",
      "about.v2p": "우리는 소량으로 가공하고, 조립하고, 테스트합니다. 모든 제품은 배송 전 손수 검수합니다.",
      "about.v3t": "오래 쓰도록 만듭니다",
      "about.v3p": "필요한 곳엔 금속을, 표준 소켓을, 교체 가능한 부품을. 매립지가 아니라 긴 수명을 얻는 하드웨어입니다.",
      "support.doc": "지원 — TypixNode",
      "support.kicker": "도움말 & 지원",
      "support.h1": "도와드리겠습니다.",
      "support.lead": "배송, 반품, 보증, 설정 — 핵심 사항은 아래에 있습니다. 그래도 막히셨나요? 이메일을 보내시면 사람이 직접 답변드립니다.",
      "support.s1t": "사전 예약 & 배송",
      "support.s1p": "모든 제품은 소량 배치로 제작되는 사전 예약 상품입니다. 예상 발송 시기는 주문 후 2주 ~ 2개월이며, 전 세계 배송입니다 (배송비는 결제 시 계산). 배송되는 즉시 추적 정보를 이메일로 보내드립니다. 일부 경로에는 관세가 부과될 수 있습니다.",
      "support.s2t": "환불 & 반품",
      "support.s2p": "사전 예약 제품이 배송되기 전이라면 언제든 전액 환불됩니다 — 이메일만 보내주세요. 배송 후에는 미사용 제품에 한해 원래 포장 상태로 30일 반품이 가능합니다.",
      "support.s3t": "보증",
      "support.s3p": "모든 기기는 제조 결함에 대해 2년 제한 보증이 적용됩니다. 수리에는 정품, 문서화된 부품을 사용합니다.",
      "support.s4t": "문의",
      "support.s4p": "support@typixnode.com으로 이메일을 보내주세요 — 보통 영업일 기준 하루 이내에 답변드립니다.",
