      "compat.kicker": "Software e compatibilità", "compat.title": "Esegui tutto ciò che ami su TypixDeck",
      "compat.sub": "Esegue Linux mainline su Raspberry Pi — quindi tutto il mondo open source viene con esso. Un assaggio di ciò che funziona subito.",
      "compat.g.os": "Sistemi operativi", "compat.g.emu": "Retrogaming ed emulatori", "compat.g.engine": "Motori di gioco e creazione",
      "compat.g.sdr": "Radio definita dal software (SDR)", "compat.g.desktop": "Desktop e sviluppo", "compat.g.media": "Media e ufficio",
      "compat.disc": "Tutti i marchi appartengono ai rispettivi proprietari; i loghi sono mostrati solo per indicare la compatibilità software.",
      "cta.home.t": "Inizia con TypixDeck",
      "cta.home.p": "Un computer Linux silenzioso, open e in alluminio CNC che sta nella tua mano. Costruito sull'ecosistema aperto di Raspberry Pi, condiviso da milioni di sviluppatori in tutto il mondo.",
      "cta.home.b1": "Scopri TypixDeck",
      "cta.home.b2": "Vedi tutti i prodotti",
      "ft.tag": "Hardware compatto e open, progettato e lavorato a CNC in piccole serie. Costruito minuscolo, spedito in tutto il mondo.",
      "ft.products": "Prodotti",
