      "ft.copy": "© 2026 TypixNode — Hardware compatto e open",
      "nl.title": "Iscriviti alla newsletter", "nl.sub": "Non perderti nulla — novità, riassortimenti e rilasci open source.",
      "nl.name": "Nome", "nl.email": "Indirizzo email", "nl.btn": "Iscriviti", "nl.sending": "Iscrizione…",
      "nl.ok": "Ci siamo quasi — controlla la posta per confermare.", "nl.already": "Sei già iscritto. Grazie!",
      "nl.invalid": "Inserisci un indirizzo email valido.", "nl.err": "Qualcosa è andato storto. Riprova.",
      "deck.h1.v1": "Un computer Linux <span class=\"grad\">sottile e tascabile.</span>",
      "deck.h1.v2": "Corpo in alluminio CNC.<br/><span class=\"grad\">Un computer intero.</span>",
      "deck.h1.v3": "Un corpo in alluminio lavorato a CNC,<br/><span class=\"grad\">sigillato in un solo pezzo.</span>",
      "deck.h1.v4": "Aprilo, modificalo,<br/><span class=\"grad\">fallo tuo.</span>",
      "deck.h1.v5": "Un computer tascabile<br/><span class=\"grad\">da aprire, modificare e tenere.</span>",
      "deck.h1.v6": "Un computer open source<br/><span class=\"grad\">fatto per gli smanettoni.</span>",
      "deck.lead": "Scopri TypixDeck — una macchina sottile e tascabile in un corpo in alluminio lavorato a CNC, costruita attorno a un Raspberry Pi Compute Module. Aprilo, modificalo, fallo tuo. Spedito in tutto il mondo.",
      "deck.add": "Aggiungi al carrello →",
      "deck.look": "Guarda all'interno",
      "deck.ship": "· spedizione in tutto il mondo",
      "deck.pricenote": "· solo corpo — senza batteria / compute module · spedizione in tutto il mondo (calcolata al checkout)",
      "deck.cm0": "+ CM0 (adattatore CM0→CM4 saldato)",
      "deck.cm4": "+ CM4 4GB completo (batteria inclusa)",
      "deck.cm5": "+ CM5 4GB completo (batteria inclusa)",
      "deck.coolnote": "CM0 / CM4 sono senza ventola &amp; silenziosi (0 dB). La versione CM5 aggiunge una ventola PWM a 4-pin opzionale + case CNC dedicato — in produzione.",
      "kb.pricenote": "· Bluetooth · versione cablata $29 · spedizione in tutto il mondo (calcolata al checkout)",
      "kb.wired": "Cablata",
      "deck.trust": "Preordine · spedizione in 2 settimane – 2 mesi · rimborso totale prima della spedizione · gira sull'ecosistema aperto di Raspberry Pi",
      "st.fanless": "Senza ventola",
      "st.alu": "Alluminio CNC",
      "st.pi": "Raspberry Pi",
      "st.open": "Open source",
      "st.social": "Costruito sulla piattaforma Raspberry Pi — un ecosistema aperto condiviso da <b>milioni</b> di sviluppatori in tutto il mondo.",
      "f.kicker": "Perché è diverso",
      "f.title": "Tutto ciò che un computer minuscolo dovrebbe essere",
      "f.sub": "Nessuna ventola che si guasta, nessuna plastica che si flette, nessun firmware bloccato — solo macchine fatte splendidamente e completamente sotto il tuo controllo.",
      "f.1t": "Chassis in alluminio CNC",
      "f.1p": "Ricavato da un unico blocco di alluminio 6061-T6, sabbiato e anodizzato. Rigido, fresco al tatto, costruito per durare decenni.",
      "f.2t": "Davvero silenzioso — 0 dB",
      "f.2p": "Lo chassis in alluminio CNC è il dissipatore — niente ventola, niente prese d'aria, niente polvere. CM0 e CM4 funzionano in totale silenzio a 0 dB. Per la potenza extra del CM5, è in lavorazione un case CNC dedicato con header per ventola PWM a 4-pin.",
      "f.3t": "Raspberry Pi CM4 / CM5 / CM0",
      "f.3p": "Inserisci il compute module che vuoi. Anche il CM0 entra tramite l'adattatore CM0→CM4 castellated a 132-pin (venduto separatamente).",
      "f.4t": "I/O completo",
      "f.4p": "HDMI, USB-C, doppio USB-A, Ethernet, GPIO a 40-pin.",
      "f.5t": "CAD e firmware open",
      "f.5p": "Ogni file STEP, schema e immagine su GitHub.",
      "f.6t": "Ingombro di una carta di credito",
      "f.6p": "Più piccolo del tuo telefono, più pesante di quanto sembri. Si infila in una borsa e fa girare un desktop Linux completo ovunque.",
      "in.kicker": "Fatto per essere aperto",
      "in.title": "Quattro viti e sei dentro.",
      "in.1": "<b>Facile da smontare.</b> Viti imperdibili, connettori etichettati e uno smontaggio documentato — niente colla da nessuna parte.",
      "in.2": "<b>Cambia il cervello.</b> Il compute module si appoggia su un socket standard. Passa al CM5 in pochi minuti.",
      "in.3": "<b>Espandilo.</b> Slot M.2 per NVMe, un header a 40-pin per gli HAT, header interni per accessori.",
      "in.4": "<b>Ripara, non sostituire.</b> Ricambi e CAD sono pubblici, così un coperchio graffiato non significa mai un nuovo computer.",
      "in.git": "CAD open su GitHub ↗",
      "r.1k": "Desktop silenzioso",
      "r.1t": "Un desktop Linux completo che non fa rumore",
      "r.1p": "Avvia direttamente Raspberry Pi OS o la distro che preferisci. Programma, SSH, naviga e smanetta — con zero rumore di ventola sulla tua scrivania.",
      "r.2k": "Input tascabile",
      "r.2t": "Si abbina a una tastiera grande come una carta",
      "r.2p": "Aggiungi la TypixNode BLE Keyboard per una postazione di lavoro tascabile completa — layout completo, air-mouse giroscopico e retroilluminazione bianca via Bluetooth o USB-C.",
      "r.3k": "Per smanettoni",
      "r.3t": "Hardware che invita alla curiosità",
      "r.3p": "Da un Mac del 1984 da palmo a un kit tastiera da saldare da soli, ogni dispositivo TypixNode è progettato per essere aperto, compreso e modificato.",
      "lu.kicker": "La gamma completa",
      "lu.title": "Quattro macchine. Scegli la tua taglia.",
      "lu.sub": "Un catalogo piccolo e curato — nessun riempitivo, ogni prodotto è qualcosa che useremmo anche noi.",
      "sp.kicker": "TypixDeck",
      "sp.title": "Specifiche tecniche",
      "sp.compute": "Compute",
      "sp.chassis": "Chassis",
      "sp.cooling": "Raffreddamento",
      "sp.storage": "Archiviazione",
