      "sp.os": "Open source",
      "sp.compute.v": "Raspberry Pi Compute Module 4 o 5 (su socket) — o CM0 tramite l'adattatore CM0→CM4 castellated a 132-pin",
      "sp.chassis.v": "Alluminio 6061-T6 fresato CNC, sabbiato e anodizzato",
      "sp.cooling.v": "Passivo 0 dB su CM0/CM4 (lo chassis è il dissipatore); il CM5 aggiunge un header per ventola PWM a 4-pin opzionale + case CNC dedicato (in sviluppo)",
      "sp.storage.v": "microSD + slot M.2 NVMe interno",
      "sp.ports.v": "HDMI, USB-C (PD), 2× USB-A, Gigabit Ethernet, GPIO a 40-pin",
      "sp.wireless.v": "Wi-Fi 5 / Bluetooth 5.0 (dipende dal CM)",
      "sp.dim.v": "95 × 62 × 22 mm · 280 g",
      "sp.os.v": "File STEP, schemi e firmware completi su GitHub",
      "faq.kicker": "Utile a sapersi",
      "faq.title": "Domande frequenti",
      "faq.q1": "Include un Raspberry Pi Compute Module?",
      "faq.a1": "Il TypixDeck viene spedito come kit chassis. Aggiungi un CM4 o CM5 al checkout, oppure inseriscine uno che possiedi già — usa il socket standard per compute module.",
      "faq.q2": "Come fa un computer senza ventola a restare fresco?",
      "faq.a2": "Lo chassis in alluminio CNC è il dissipatore. Il compute module è accoppiato termicamente allo chassis, così il calore si distribuisce su tutto il corpo e si dissipa in silenzio, anche sotto carico prolungato.",
      "faq.q3": "Posso davvero aprirlo e ripararlo da solo?",
      "faq.a3": "Sì. Quattro viti imperdibili, niente colla, connettori etichettati e una guida pubblica allo smontaggio. Ricambi e file CAD sono disponibili così puoi riparare o modificare qualsiasi cosa.",
      "faq.q4": "Quando viene spedito il mio preordine?",
      "faq.a4": "Tutti gli articoli sono in preordine, prodotti in piccole serie. La spedizione stimata è di 2 settimane – 2 mesi dall'ordine; inviamo il tracking via email quando spedisce. Spedizione in tutto il mondo (calcolata al checkout) e rimborso totale in qualsiasi momento prima della spedizione. Potrebbero applicarsi dazi a seconda della tua regione.",
      "cta.deck.t": "Costruisci il tuo laboratorio Linux tascabile",
      "cta.deck.p": "Silenzioso, open e fatto per essere aperto. Alimentato dalla piattaforma Raspberry Pi e dal suo ecosistema aperto di milioni di sviluppatori in tutto il mondo.",
      "cta.deck.b2": "Vedi tutti i prodotti",
